import math
import sys

def cross_simple(x, y, r, tx, ty, tr):
    d2 = (tx - x) ** 2 + (ty - y) ** 2
    if d2 < (r - tr) ** 2:
        return []
    if d2 > (r + tr) ** 2:
        return []
    base = math.atan2(ty - y, tx - x)
    wing = math.acos((d2 + r ** 2 - tr ** 2) / (2.0 * math.sqrt(d2) * r))
    inf = base - wing
    sup = base + wing
    return [inf, sup]

def d2(ax, ay, bx, by):
    return (bx - ax) ** 2 + (by - ay) ** 2

def main():
    input = sys.stdin.read().splitlines()
    n = int(input[0].strip())
    co = []
    for i in range(1, n + 1):
        parts = input[i].strip().split()
        co.append([int(parts[0]), int(parts[1]), int(parts[2])])
    nodes = []
    p = 0
    for i in range(n):
        for j in range(i + 1, n):
            ts = cross_simple(co[i][0], co[i][1], co[i][2], co[j][0], co[j][1], co[j][2])
            for t in ts:
                nodes.append([
                    co[i][0] + co[i][2] * math.cos(t),
                    co[i][1] + co[i][2] * math.sin(t)
                ])
                p += 1
    # Remove duplicates
    unique_nodes = []
    for i in range(p):
        skip = False
        for j in range(i):
            if d2(nodes[i][0], nodes[i][1], nodes[j][0], nodes[j][1]) < 1e-12:
                skip = True
                break
        if not skip:
            unique_nodes.append(nodes[i])
    nnodes = len(unique_nodes)
    q = 0
    filtered_nodes = []
    for i in range(nnodes):
        node = unique_nodes[i]
        skip_node = False
        for j in range(nnodes):
            if i != j:
                if d2(node[0], node[1], unique_nodes[j][0], unique_nodes[j][1]) < 1e-12:
                    skip_node = True
                    break
        if not skip_node:
            filtered_nodes.append(node)
    q = len(filtered_nodes)
    ne = 0
    con = 1
    for j in range(n):
        e = 0
        for i in range(q):
            if abs(d2(filtered_nodes[i][0], filtered_nodes[i][1], co[j][0], co[j][1]) - co[j][2] ** 2) < 1e-12:
                e += 1
        if e == 0:
            con += 1
        ne += e
    if con > n:
        con = n
    print(ne - nnodes + con + 1)

if __name__ == "__main__":
    main()

